def load_prompt_templates(override_path: str | None = None) -> dict[str, str]:
    """Templates to sync: MAILROOM_PROMPTS JSON file wins over the mirror."""
    path = override_path or os.environ.get("MAILROOM_PROMPTS")
    if path:
        data = json.loads(Path(path).read_text(encoding="utf-8"))
        if not isinstance(data, dict) or not all(isinstance(v, str) for v in data.values()):
            raise ValueError(f"{path}: expected a JSON object of agent_name -> template")
        return data
    return dict(PROMPT_TEMPLATES)


def prompt_name(agent_name: str) -> str:
    """Langfuse prompt-management name for an agent (upstream contract)."""
    return f"mailroom-{agent_name}"
